import React from 'react';
import './MovieCategories.css';
import Icon from './Icon';

function MovieCategories({ genres, selectedGenre, onSelectGenre }) {
  const genreIcons = {
    'Tất cả': <Icon name="play" />,
    'Hoạt Hình': <Icon name="play" />,
    'Hành Động': <Icon name="flame" animation="flame" />,
    'Viễn Tưởng': <Icon name="star" animation="rotate" />,
    'Kinh Dị': <Icon name="flame" animation="flame" />,
    'Tình Cảm': <Icon name="heart" animation="heartbeat" />,
    'Hài Kịch': <Icon name="star" />,
    'Tâm Lý': <Icon name="star" />,
    'Dạo Mạo': <Icon name="play" />,
    'Trinh Thám': <Icon name="search" />
  };

  return (
    <section className="movie-categories">
      <h2>Khám Phá Thể Loại</h2>
      <div className="categories-list">
        {genres.map((genre) => (
          <button
            key={genre}
            className={`category-button ${selectedGenre === genre ? 'active' : ''}`}
            onClick={() => onSelectGenre(genre)}
          >
            <span className="genre-emoji">{genreIcons[genre] || <Icon name="play" />}</span>
            <span className="genre-name">{genre}</span>
          </button>
        ))}
      </div>
    </section>
  );
}

export default MovieCategories;
